ValidationRule.errorConditionFormula:
OR(
    /* 1) Name starts with RECOMMENDER/DECLARATION but category ≠ Details */
    AND(
        NOT( ISPICKVAL(Issue_Category__c, "") ),
        OR(
            BEGINS( UPPER(TRIM(Name)), "RECOMMENDER" ),
            BEGINS( UPPER(TRIM(Name)), "DECLARATION" )
        ),
        NOT( ISPICKVAL(Issue_Category__c, "Details") )
    ),
    /* 2) Name starts with RESUME but category ≠ Document */
    AND(
        NOT( ISPICKVAL(Issue_Category__c, "") ),
        BEGINS( UPPER(TRIM(Name)), "RESUME" ),
        NOT( ISPICKVAL(Issue_Category__c, "Document") )
    ),
    /* 3) If confidence > 95, any non‑blank picklist is invalid */
    AND(
        Percentage_Confidence__c > 95,
        /* picklist blank check */
        NOT( ISPICKVAL(Issue_Category__c, "") )
    )
)
